const upsertBackdropChannelVideos = `-- name: UpsertBackdropChannelVideos :exec
INSERT INTO backdrop_channel_videos (
    channel_id, video_id, kind, url, title, duration_sec, thumbnail_url, published_at, position, listed_at
)
SELECT
    $1::text, v.video_id, v.kind, v.url, coalesce(v.title, ''),
    v.duration_sec, v.thumbnail_url, v.published_at, v.position, $2::timestamptz
FROM jsonb_to_recordset($3::jsonb) AS v(
    video_id text, kind text, url text, title text, duration_sec real,
    thumbnail_url text, published_at timestamptz, position integer
)
ON CONFLICT (channel_id, video_id) DO UPDATE SET
    kind = excluded.kind,
    url = excluded.url,
    position = excluded.position,
    listed_at = excluded.listed_at,
    title = coalesce(nullif(excluded.title, ''), backdrop_channel_videos.title),
    duration_sec = coalesce(excluded.duration_sec, backdrop_channel_videos.duration_sec),
    thumbnail_url = coalesce(excluded.thumbnail_url, backdrop_channel_videos.thumbnail_url),
    published_at = coalesce(excluded.published_at, backdrop_channel_videos.published_at),
    unavailable_at = CASE
        WHEN backdrop_channel_videos.unavailable_reason IN ('expired', 'live') THEN NULL
        ELSE backdrop_channel_videos.unavailable_at END,
    unavailable_reason = CASE
        WHEN backdrop_channel_videos.unavailable_reason IN ('expired', 'live') THEN NULL
        ELSE backdrop_channel_videos.unavailable_reason END
`

type UpsertBackdropChannelVideosParams struct {
	ChannelID string             `json:"channel_id"`
	ListedAt  pgtype.Timestamptz `json:"listed_at"`
	Videos    []byte             `json:"videos"`
}

// Ghi một lượt đọc danh sách: trường đã dò (duration, ảnh, ngày đăng) sống
// sót khi danh sách không mang, lý do tự hết (expired/live) được xoá.
func (q *Queries) UpsertBackdropChannelVideos(ctx context.Context, arg UpsertBackdropChannelVideosParams) error {
	_, err := q.db.Exec(ctx, upsertBackdropChannelVideos, arg.ChannelID, arg.ListedAt, arg.Videos)
	return err
}

const usableBackdropCounts = `-- name: UsableBackdropCounts :many
SELECT channel_id, kind, count(*)::int AS total
FROM backdrop_channel_videos
WHERE channel_id = ANY($1::text[]) AND unavailable_at IS NULL
GROUP BY channel_id, kind
`

type UsableBackdropCountsRow struct {
	ChannelID string `json:"channel_id"`
	Kind      string `json:"kind"`
	Total     int32  `json:"total"`
}

func (q *Queries) UsableBackdropCounts(ctx context.Context, channelIds []string) ([]UsableBackdropCountsRow, error) {
	rows, err := q.db.Query(ctx, usableBackdropCounts, channelIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []UsableBackdropCountsRow{}
	for rows.Next() {
		var i UsableBackdropCountsRow
		if err := rows.Scan(&i.ChannelID, &i.Kind, &i.Total); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
